import{_ as a,o as e,c as d,O as l}from"./chunks/framework.db831a78.js";const b=JSON.parse('{"title":"系统设计（架构与设计方法论）","description":"","frontmatter":{},"headers":[],"relativePath":"backend/系统设计/index.md","filePath":"backend/系统设计/index.md","lastUpdated":1788941422000}'),i={name:"backend/系统设计/index.md"};function r(o,t,h,n,s,u){return e(),d("div",null,t[0]||(t[0]=[l('<h1 id="系统设计-架构与设计方法论" tabindex="-1">系统设计（架构与设计方法论） <a class="header-anchor" href="#系统设计-架构与设计方法论" aria-label="Permalink to &quot;系统设计（架构与设计方法论）&quot;">​</a></h1><blockquote><p>从架构原则、领域建模到微服务与高并发，面向后端面试与实战的&quot;判断框架优先、具体模式其次&quot;的系统设计方法论合集。</p></blockquote><hr><h2 id="一、系列定位" tabindex="-1">一、系列定位 <a class="header-anchor" href="#一、系列定位" aria-label="Permalink to &quot;一、系列定位&quot;">​</a></h2><h3 id="_1-1-与既有笔记的边界" tabindex="-1">1.1 与既有笔记的边界 <a class="header-anchor" href="#_1-1-与既有笔记的边界" aria-label="Permalink to &quot;1.1 与既有笔记的边界&quot;">​</a></h3><p>本系列定位为<strong>方法论与决策层</strong>，刻意与既有的组件用法类笔记互补、不重复：</p><table><thead><tr><th>既有笔记</th><th>讲什么</th><th>本系列的补充</th></tr></thead><tbody><tr><td><a href="./../Java/SpringCloud微服务">SpringCloud微服务</a></td><td>Nacos / Gateway / Sentinel / Seata 等组件的安装、配置、API 用法</td><td>为什么要拆、何时不该拆、通信与一致性模式的取舍逻辑</td></tr><tr><td><a href="./../Java/消息队列">消息队列</a></td><td>MQ 产品特性与使用</td><td>MQ 在削峰、异步化、最终一致性中的系统级定位</td></tr><tr><td><a href="./../../database/Redis">Redis</a>、<a href="./../../database/MySQL深入">MySQL深入</a></td><td>中间件能力与调优</td><td>缓存体系决策、读写分离与分库分表决策树</td></tr></tbody></table><p>阅读约定：凡是&quot;如何配置某个组件&quot;都指向上述组件笔记，本系列只回答&quot;选哪个、为什么、边界在哪、如何判断&quot;。</p><h3 id="_1-2-阅读顺序建议" tabindex="-1">1.2 阅读顺序建议 <a class="header-anchor" href="#_1-2-阅读顺序建议" aria-label="Permalink to &quot;1.2 阅读顺序建议&quot;">​</a></h3><ol><li>先读《设计原则与架构演进》建立全局观；</li><li>再读《DDD领域驱动设计》理解领域建模与边界；</li><li>然后读《微服务架构与拆分》把边界落成服务；</li><li>《高并发系统设计》与《经典系统设计案例》解决性能与容量问题，两者可对照阅读；</li><li>面试前用本篇尾部的题单自测。</li></ol><hr><h2 id="二、系列覆盖表" tabindex="-1">二、系列覆盖表 <a class="header-anchor" href="#二、系列覆盖表" aria-label="Permalink to &quot;二、系列覆盖表&quot;">​</a></h2><table><thead><tr><th>文件</th><th>一句话定位</th><th>关键交付物</th></tr></thead><tbody><tr><td>设计原则与架构演进</td><td>架构层如何理解设计原则，单体到平台化的演进逻辑与代价</td><td>演进决策对照表、过度设计信号清单</td></tr><tr><td>DDD领域驱动设计</td><td>用战略设计与战术设计把复杂业务建模成可落地的代码边界</td><td>电商订单模块包结构与充血模型示例代码</td></tr><tr><td>微服务架构与拆分</td><td>拆分方法论、通信/注册中心/网关选型与分布式事务模式取舍</td><td>拆分决策树、一致性模式对比表</td></tr><tr><td>高并发系统设计</td><td>容量评估与分层防护的完整方法论</td><td>通用 8 步设计法、四保护策略指标表</td></tr><tr><td>经典系统设计案例</td><td>短链、秒杀、Feed、IM 四个端到端案例</td><td>4 张架构图、分布式 ID 与限流算法附表</td></tr></tbody></table><hr><h2 id="三、文章导航" tabindex="-1">三、文章导航 <a class="header-anchor" href="#三、文章导航" aria-label="Permalink to &quot;三、文章导航&quot;">​</a></h2><ul><li><a href="./设计原则与架构演进">设计原则与架构演进</a>：单一职责、开闭、依赖倒置在架构层的投影，以及单体到中台化的演进驱动与代价。</li><li><a href="./DDD领域驱动设计">DDD领域驱动设计</a>：限界上下文与聚合建模，贫血 vs 充血模型，附电商订单 DDD 落地代码骨架。</li><li><a href="./微服务架构与拆分">微服务架构与拆分</a>：从四个视角拆服务，服务间通信与基础设施选型，分布式事务模式取舍与&quot;何时不该上微服务&quot;。</li><li><a href="./高并发系统设计">高并发系统设计</a>：容量评估、分层防护、缓存与异步化决策，隔离/熔断/降级/限流选型，附通用 8 步设计法。</li><li><a href="./经典系统设计案例">经典系统设计案例</a>：短链、秒杀、Feed、IM 四案例端到端拆解，附分布式 ID 与限流算法对比表。</li></ul><hr><h2 id="四、学完可回答的系统设计面试题" tabindex="-1">四、学完可回答的系统设计面试题 <a class="header-anchor" href="#四、学完可回答的系统设计面试题" aria-label="Permalink to &quot;四、学完可回答的系统设计面试题&quot;">​</a></h2><ol><li>说说架构演进通常经历哪几个阶段？每一步的驱动因素和代价是什么？如何判断自己该不该走到微服务？</li><li>单一职责原则在模块/服务层面怎么落地？拆服务和拆类有什么不同的判断标准？</li><li>什么是限界上下文？它和微服务边界是什么关系？如何用 DDD 指导一次服务拆分？</li><li>贫血模型和充血模型有什么区别？为什么实际项目里贫血模型这么多？如何渐进改进？</li><li>拆分微服务有哪些方法（按业务能力 / 子域 / 团队 / 变更频率）？如何评估拆分的粒度是否合适？</li><li>服务间通信选同步还是异步？什么时候必须用 MQ？消息带来的重复、乱序、丢消息怎么兜底？</li><li>对比 2PC、TCC、SAGA、本地消息表、事务消息的适用场景，电商下单一般怎么选？如何尽量避免分布式事务？</li><li>如何估算一个系统的 QPS 并推导容量？压测目标怎么定？</li><li>缓存穿透、击穿、雪崩分别怎么防？缓存与数据库的一致性如何取舍？</li><li>熔断、降级、限流、隔离各自的适用场景与关键指标是什么？秒杀场景为什么要&quot;本地标记 + MQ 削峰 + 库存预扣&quot;？</li><li>短链系统用哈希还是发号器？跳转链路和过期清理如何设计？</li><li>设计一个高可用 IM 或 Feed 流系统，消息可靠性（不丢不重不乱序）如何保证？</li><li>分布式 ID 有哪些生成方案？为什么很多系统选雪花算法，它的时钟回拨问题怎么处理？</li></ol>',19)]))}const q=a(i,[["render",r]]);export{b as __pageData,q as default};
